#if defined (__BUILD_GADGETRON_GPU__) || defined (gpusolvers_EXPORTS)
#define EXPORTGPUSOLVERS __declspec(dllexport)
#else
#define EXPORTGPUSOLVERS __declspec(dllimport)
#endif
#else
#define EXPORTGPUSOLVERS
